// The controller moves focus and presses buttons: Lamp's lamp.js gives the d-pad and left stick as arrow keys, A as
// Enter and B as Escape.
function focusables() { return Array.prototype.slice.call(document.querySelectorAll(".focusable")); }

// Moves focus to the nearest focusable thing in the direction of an arrow (the controller's d-pad and stick).
document.addEventListener("keydown", function (e) {
  var dirs = { ArrowUp: [0, -1], ArrowDown: [0, 1], ArrowLeft: [-1, 0], ArrowRight: [1, 0] };
  var d = dirs[e.key];
  if (!d) return;
  var current = document.activeElement, items = focusables();
  if (!current || items.indexOf(current) < 0) { if (items[0]) items[0].focus(); return; }
  var r = current.getBoundingClientRect(), best = null, bestScore = Infinity;
  items.forEach(function (el) {
    if (el === current) return;
    var o = el.getBoundingClientRect();
    var dx = (o.left + o.width / 2) - (r.left + r.width / 2), dy = (o.top + o.height / 2) - (r.top + r.height / 2);
    if (dx * d[0] + dy * d[1] <= 0) return;
    var score = Math.abs(dx * d[0] + dy * d[1]) + 2 * Math.abs(dx * d[1] + dy * d[0]);
    if (score < bestScore) { bestScore = score; best = el; }
  });
  if (best) { best.focus(); e.preventDefault(); }
});

window.addEventListener("load", function () { var f = focusables()[0]; if (f) f.focus(); });

