  font-family: "Segoe UI", sans-serif; }
#app { padding: 96px 120px; }
h1 { font-size: 88px; margin: 0 0 24px; }
p { font-size: 40px; opacity: .8; }
button { font: inherit; font-size: 40px; padding: 20px 48px; border-radius: 16px; border: 4px solid transparent;
  background: #2a3042; color: inherit; }
button:focus { outline: none; border-color: #7aa2ff; transform: scale(1.06); }
